import { CSSProperties } from 'react';
import { css, FlattenSimpleInterpolation } from 'styled-components';

const regex = new RegExp(/[A-Z]/g);
const kebabCase = (str: string) =>
  str.replace(regex, (v) => `-${v.toLowerCase()}`);

/**
 * uses camelCase React.CSSProperties and returns a styled-component css string in kebab-case
 */
export function convertCSSPropertiesToStyled(
  cssProperties: CSSProperties,
): FlattenSimpleInterpolation {
  return css`
    ${Object.entries(cssProperties).reduce((accumulator, [key, value]) => {
      const cssKey = kebabCase(key);
      const cssValue =
        typeof value === 'string' ? value.replace("'", '') : value;
      return `${accumulator}${cssKey}:${cssValue};`;
    }, '')}
  `;
}
